import {icon} from './icons.js';
import {ingredients,recipes,missing,ingredientName} from './data.js';
/** @typedef {import('./data.js').Recipe} Recipe */
/** @typedef {'home'|'pantry'|'detail'|'camera'|'review'|'cook'|'done'} Screen */
const mount=document.querySelector('#app');
if(!(mount instanceof HTMLElement)) throw new Error('App mount missing');
const app=mount;
/** @type {Screen} */ let screen='home';
let recipe=recipes[0];
let step=0;
let group='전체';
let search='';
let storageError='';
let error='';
let cameraPending=false;
let photoPending=false;
let cameraRequest=0;
let photoRequest=0;
let photo='';
let previous='home';
/** @type {MediaStream|null} */ let stream=null;
/** @type {Set<string>} */ let draft=new Set();
/** @param {string} key @param {string[]} fallback */
function loadIds(key,fallback){try{const raw=localStorage.getItem(key);return new Set((raw===null?fallback:raw.split(',')).filter(id=>ingredients.some(item=>item.id===id)));}catch{storageError='이 브라우저에서는 재료를 저장할 수 없어요. 지금 선택한 내용은 이 화면에서 사용할 수 있어요.';return new Set(fallback);}}
const pantry=loadIds('round08-pantry',['tomato','egg','rice','mushroom','tofu','onion']);
const selected=loadIds('round08-selected',[...pantry]);
for(const id of selected){if(!pantry.has(id))selected.delete(id);}
/** @param {string} value */
function escape(value){return value.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');}
/** @param {string} action @param {string} label @param {string} name */
const iconButton=(action,label,name)=>`<button class="iconbtn" data-action="${action}" aria-label="${label}">${icon(name)}</button>`;
function save(){try{localStorage.setItem('round08-pantry',[...pantry].join(','));localStorage.setItem('round08-selected',[...selected].join(','));storageError='';}catch{storageError='재료를 저장하지 못했어요. 이 화면의 선택은 유지돼요.';}}
function stopCamera(){cameraRequest++;cameraPending=false;photoRequest++;photoPending=false;stream?.getTracks().forEach(track=>track.stop());stream=null;}
/** @param {Screen} next */
function go(next){if(next!=='camera')stopCamera();screen=next;error='';render();window.scrollTo(0,0);document.querySelector('h1')?.focus({preventScroll:true});}
function clearPhoto(){if(photo.startsWith('blob:'))URL.revokeObjectURL(photo);photo='';}
/** @param {string} title @param {string} right */
function header(title,right=''){return `<header class="top inset"><h1 tabindex="-1">${title}</h1>${right}</header>`;}
function nav(){return `<nav class="nav" aria-label="주요 메뉴"><button data-action="home" ${screen==='home'?'aria-current="page"':''}>${icon('utensils')}오늘의 요리</button><button data-action="pantry" ${screen==='pantry'?'aria-current="page"':''}>${icon('refrigerator')}내 냉장고</button></nav>`;}
/** @param {Recipe} dish @param {boolean} compact */
function card(dish,compact){const count=missing(dish,selected).length;return `<button class="recipe-card ${compact?'compact':''}" data-recipe="${dish.id}" aria-label="${dish.name} 자세히 보기"><img src="assets/${dish.photo}" alt="${dish.name}"><div><h2>${dish.name}</h2><div class="meta"><span>${dish.minutes}분</span><span>${count?`재료 ${count}개 더 필요`:'고른 재료로 만들어요'}</span></div></div></button>`;}
function home(){const sorted=[...recipes].sort((a,b)=>missing(a,selected).length-missing(b,selected).length);return `${header('오늘 뭐 먹지?')}<main class="inset bottom-space"><div class="summary"><div><span class="small muted">요리에 쓸 재료</span><p class="selected-summary">${selected.size?escape([...selected].slice(0,3).map(ingredientName).join(' · '))+(selected.size>3?` 외 ${selected.size-3}개`:''):'재료를 골라주세요'}</p></div>${selected.size?'<button class="secondary" data-action="pantry">바꾸기</button>':''}</div><p class="small gap">예시 재료와 요리로 체험하고 있어요.</p>${selected.size?`<section class="recipes" aria-label="선택한 재료에 맞는 요리">${sorted.map((dish,index)=>card(dish,index>0)).join('')}</section>`:`<section class="empty"><h2>냉장고에 뭐가 있나요?</h2><p>재료를 고르면 만들 수 있는 요리를 찾아요.</p><button class="primary" data-action="pantry">재료 고르기${icon('arrow-right')}</button></section>`}</main>${nav()}`;}
function pantryScreen(){const matches=ingredients.filter(item=>pantry.has(item.id)&&(group==='전체'||item.group===group));return `${header('내 냉장고',iconButton('camera','사진으로 재료 등록','camera'))}<main class="inset pantry-scroll"><p>오늘 요리에 쓸 재료를 골라주세요.</p><div class="filters" aria-label="재료 종류">${['전체','채소','달걀·두부','곡물'].map(name=>`<button class="chip" data-group="${name}" aria-pressed="${group===name}">${name}</button>`).join('')}</div><div class="section-head pantry-heading"><div class="heading-count"><h2>${group==='전체'?'보관 재료':group}</h2><span class="count-tag">${matches.length}개</span></div><button class="iconbtn add-ingredient" data-action="manual" aria-label="재료 추가">${icon('plus')}</button></div>${matches.length?`<ul class="ingredients">${matches.map(item=>`<li><label class="ingredient-row selection"><span>${item.name}<small>${item.amount}</small></span><input type="checkbox" data-select="${item.id}" aria-label="${item.name} 선택" ${selected.has(item.id)?'checked':''}></label></li>`).join('')}</ul>`:`<section class="empty"><h2>등록한 재료가 없어요</h2><p>사진을 찍거나 직접 재료를 추가해 주세요.</p></section>`}</main><footer class="pantry-dock"><div class="inset pantry-action"><button class="primary wide" data-action="home">${selected.size}개 재료로 요리 보기${icon('arrow-right')}</button></div>${nav()}</footer>`;}
function detail(){const absent=missing(recipe,selected);return `<main><div class="cover"><img class="detail-photo" src="assets/${recipe.photo}" alt="${recipe.name}">${iconButton('back','요리 목록으로','chevron-left')}</div><div class="detail-content inset"><h1 tabindex="-1">${recipe.name}</h1><div class="meta"><span>${icon('clock')}${recipe.minutes}분</span><span>쉬움</span></div><p>${recipe.description}</p><button class="primary wide" data-action="start">요리 시작${icon('arrow-right')}</button><div class="section-head space"><h2>필요한 재료</h2><span class="small muted">1인분 기준</span></div><ul class="ingredients">${recipe.ingredients.map((id,index)=>`<li class="ingredient-row"><span>${ingredientName(id)}<small>${recipe.amounts[index]}</small></span><span class="state">${selected.has(id)?'선택한 재료':'추가로 필요해요'}</span></li>`).join('')}</ul><p class="notice">${recipe.id==='tofu-rice'?'고추장·간장·식용유':'소금·간장·식용유·후추'}도 준비해 주세요.${absent.length?' 부족한 재료를 준비한 뒤 시작해 주세요.':''}</p></div></main>`;}
function camera(){return `${header('사진으로 재료 등록',iconButton('cancel','등록 취소','x'))}<main class="inset screen-form"><div id="camera-area">${stream?'<video id="video" class="capture-view" autoplay muted playsinline aria-label="카메라 미리보기"></video>':`<div class="camera-placeholder">${icon('camera')}<h2>냉장고 속 재료를 담아주세요</h2><p>촬영한 사진을 보며 재료를 골라 등록해요.</p></div>`}</div><div class="button-stack">${stream?`<button class="primary wide" data-action="capture">${icon('camera')}사진 찍기</button>`:`<button class="primary wide" data-action="enable-camera" ${cameraPending?'disabled aria-busy="true"':''}>${icon('camera')}${cameraPending?'카메라 연결 중':'카메라 켜기'}</button>`}<button class="secondary wide" data-action="upload" ${photoPending?'disabled aria-busy="true"':''}>${icon('image')}${photoPending?'사진 불러오는 중':'앨범에서 선택'}</button><button class="secondary wide" data-action="manual">${icon('plus')}직접 재료 선택</button></div><input id="upload" type="file" accept="image/*" hidden><p id="camera-error" class="error" role="alert" ${error?'':'hidden'}>${escape(error)}</p></main>`;}
function review(){return `${header(photo?'사진 속 재료 확인':'재료 추가',iconButton('cancel','등록 취소','x'))}<main class="inset screen-form">${photo?`<img class="capture-view" src="${photo}" alt="등록할 재료 사진"><p class="gap">사진에 있는 재료를 직접 골라주세요.</p>`:''}<label class="search-label" for="ingredient-search">재료 찾기</label><input id="ingredient-search" type="search" value="${escape(search)}" placeholder="토마토, 달걀, 버섯"><div id="ingredient-results">${reviewList()}</div><button id="register" class="primary wide space" data-action="register" ${draft.size?'':'disabled'}>${draft.size}개 재료 등록${icon('check')}</button></main>`;}
function reviewList(){const found=ingredients.filter(item=>item.name.includes(search.trim()));return found.length?`<ul class="ingredients">${found.map(item=>`<li><label class="ingredient-row selection"><span>${item.name}${pantry.has(item.id)?'<small>냉장고에 등록되어 있어요</small>':''}</span><input type="checkbox" data-draft="${item.id}" aria-label="${item.name} 등록 선택" ${draft.has(item.id)?'checked':''}></label></li>`).join('')}</ul>`:'<div class="empty"><h2>찾는 재료가 없어요</h2><p>이번 체험에서는 토마토·달걀 등 8가지 재료를 등록할 수 있어요.</p></div>';}
function cooking(){return `${header(recipe.name,iconButton('detail','조리 닫기','x'))}<main class="inset screen-form"><p class="step-count">${step+1} / ${recipe.steps.length} 단계</p><ol class="step-list">${recipe.steps.map((text,index)=>`<li class="step-card ${index===step?'current':''}" ${index===step?'aria-current="step"':''}><span class="small muted">${index+1}단계 · ${index===0?'재료 준비':index===recipe.steps.length-1?'마무리':'조리하기'}</span>${index===step?`<h2>${text}</h2>`:`<p>${text}</p>`}</li>`).join('')}</ol><div class="step-actions"><button class="secondary" data-action="previous" ${step===0?'disabled':''}>이전</button><button class="primary" data-action="next">${step===recipe.steps.length-1?'요리 완료':'다음 단계'}${icon(step===recipe.steps.length-1?'check':'arrow-right')}</button></div></main>`;}
function render(){const pages={home,pantry:pantryScreen,detail,camera,review,cook:cooking,done:()=>`${header('한 끼가 완성됐어요')}<main class="inset"><img class="step-photo" src="assets/${recipe.photo}" alt="${recipe.name}"><h2 class="space">${recipe.name}</h2><p class="gap">맛있게 드세요.</p><button class="primary wide space" data-action="home">다른 요리 보기${icon('arrow-right')}</button></main>`};app.classList.toggle('pantry-layout',screen==='pantry');app.innerHTML=pages[screen]();if(storageError)app.insertAdjacentHTML('afterbegin',`<p class="error" role="alert">${escape(storageError)}</p>`);}
/** @param {string} message */
function cameraError(message){error=message;const target=document.querySelector('#camera-error');if(target instanceof HTMLElement){target.hidden=false;target.textContent=message;}}
async function enableCamera(){
 if(cameraPending)return;
 if(!navigator.mediaDevices?.getUserMedia){cameraError('이 브라우저에서는 카메라를 켤 수 없어요. 앨범에서 사진을 선택해 주세요.');return;}
 const request=++cameraRequest;cameraPending=true;render();
 try{const next=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'},audio:false});
  if(screen!=='camera'||request!==cameraRequest){next.getTracks().forEach(track=>track.stop());return;}
  cameraPending=false;stream=next;render();const video=document.querySelector('#video');
  if(video instanceof HTMLVideoElement){video.srcObject=stream;await video.play();}
 }catch{if(screen!=='camera'||request!==cameraRequest)return;stopCamera();render();cameraError('카메라를 열지 못했어요. 브라우저의 카메라 권한을 확인하거나 앨범에서 사진을 선택해 주세요.');}
}
function capture(){const video=document.querySelector('#video');if(!(video instanceof HTMLVideoElement)||!video.videoWidth){cameraError('카메라 화면을 아직 불러오지 못했어요. 잠시 후 다시 찍어주세요.');return;}const canvas=document.createElement('canvas');canvas.width=video.videoWidth;canvas.height=video.videoHeight;const context=canvas.getContext('2d');if(!context){cameraError('사진을 만들지 못했어요. 앨범에서 선택해 주세요.');return;}context.drawImage(video,0,0);clearPhoto();photo=canvas.toDataURL('image/jpeg',.85);draft=new Set();search='';go('review');}
app.addEventListener('click',event=>{if(!(event.target instanceof Element))return;const target=event.target.closest('button');if(!target)return;const id=target.dataset.recipe;if(id){const match=recipes.find(item=>item.id===id);if(match){recipe=match;go('detail');}return;}if(target.dataset.group){group=target.dataset.group;render();const restored=document.querySelector(`[data-group="${group}"]`);if(restored instanceof HTMLElement)restored.focus();return;}switch(target.dataset.action){case'home':go('home');break;case'pantry':go('pantry');break;case'back':go('home');break;case'detail':go('detail');break;case'camera':previous=screen;clearPhoto();go('camera');break;case'cancel':clearPhoto();go(previous==='home'?'home':'pantry');break;case'manual':previous=screen==='pantry'?'pantry':previous;clearPhoto();draft=new Set();search='';go('review');break;case'upload':{const input=document.querySelector('#upload');if(input instanceof HTMLInputElement)input.click();break;}case'enable-camera':void enableCamera();break;case'capture':capture();break;case'register':if(draft.size){for(const value of draft){pantry.add(value);selected.add(value);}save();clearPhoto();group='전체';go('pantry');}break;case'start':step=0;go('cook');break;case'previous':if(step>0){step--;render();const control=document.querySelector(step===0?'[data-action=next]':'[data-action=previous]');if(control instanceof HTMLElement)control.focus();}break;case'next':if(step<recipe.steps.length-1){step++;render();const control=document.querySelector('[data-action=next]');if(control instanceof HTMLElement)control.focus();}else go('done');break;}});
app.addEventListener('change',async event=>{const target=event.target;if(!(target instanceof HTMLInputElement))return;if(target.dataset.select){if(target.checked)selected.add(target.dataset.select);else selected.delete(target.dataset.select);save();render();const restored=document.querySelector(`[data-select="${target.dataset.select}"]`);if(restored instanceof HTMLElement)restored.focus();return;}if(target.dataset.draft){if(target.checked)draft.add(target.dataset.draft);else draft.delete(target.dataset.draft);const button=document.querySelector('#register');if(button instanceof HTMLButtonElement){button.disabled=!draft.size;button.innerHTML=`${draft.size}개 재료 등록${icon('check')}`;}return;}if(target.id==='upload'){const file=target.files?.[0];if(!file)return;if(!file.type.startsWith('image/')||file.size>10*1024*1024){cameraError('10MB 이하의 이미지 파일을 선택해 주세요.');target.value='';return;}const request=++photoRequest;photoPending=true;render();const next=URL.createObjectURL(file);const preview=new Image();preview.src=next;try{await preview.decode();if(screen!=='camera'||request!==photoRequest){URL.revokeObjectURL(next);return;}photoPending=false;clearPhoto();photo=next;draft=new Set();search='';go('review');}catch{URL.revokeObjectURL(next);if(screen!=='camera'||request!==photoRequest)return;photoPending=false;render();cameraError('이 사진을 읽을 수 없어요. JPG 또는 PNG 사진으로 다시 선택해 주세요.');target.value='';}}});
app.addEventListener('input',event=>{const target=event.target;if(!(target instanceof HTMLInputElement)||target.id!=='ingredient-search')return;search=target.value;const results=document.querySelector('#ingredient-results');if(results)results.innerHTML=reviewList();});
window.addEventListener('pagehide',stopCamera);
render();
